import { defineTool as D, numberField as F, metric as M } from '@jarvis/components/toolkit/science50/model';
export const controlTools=[
D({id:'first-order-response',title:'First-Order Step Response',desc:'Explore gain, time constant, transport delay and settling after a step.',tone:'violet',sweep:'time',fields:[F('gain','Steady process gain',1,-100,100),F('amplitude','Input step amplitude',1,-100,100),F('tau','Time constant (s)',2,.0001,1e5),F('delay','Transport delay (s)',.5,0,1e5),F('time','Elapsed time (s)',5,0,1e6)],equation:'y(t) = K·A·[1−exp(−(t−delay)/τ)] for t > delay',note:'Linear stable first-order plant, zero initial output and a single input step. Transport delay shifts the response but does not change the final gain.',calculate:p=>({primary:M('Output at selected time',p.gain*p.amplitude*(-Math.expm1(-Math.max(0,p.time-p.delay)/p.tau))),metrics:[M('Final output',p.gain*p.amplitude),M('99% settling time',p.delay+Math.log(100)*p.tau,'s'),M('Plant pole',-1/p.tau,'1/s'),M('Time since delayed step',Math.max(0,p.time-p.delay),'s')]}),references:[{label:'One time constant',input:{gain:1,amplitude:1,tau:1,delay:0,time:1},expected:1-1/Math.E},{label:'Two time constants',input:{gain:2,amplitude:1,tau:1,delay:0,time:2},expected:2*(1-Math.exp(-2))}]}),
D({id:'second-order-response',title:'Second-Order Step Response',desc:'Compare underdamped, critically damped and overdamped dynamics.',tone:'violet',sweep:'time',fields:[F('frequency','Natural angular frequency (rad/s)',2,.0001,1e4),F('damping','Damping ratio ζ',.4,.01,5),F('gain','Steady gain',1,-100,100),F('amplitude','Input step amplitude',1,-100,100),F('time','Elapsed time (s)',3,0,1e5)],equation:'G(s) = Kωn² / (s² + 2ζωn s + ωn²)',note:'Exact zero-state step response of a stable second-order transfer function. Settling time is a dominant-mode approximation, not an exact tolerance-band crossing.',calculate:p=>{const a=p.damping*p.frequency,t=p.time;let response;if(Math.abs(p.damping-1)<1e-9)response=1-Math.exp(-p.frequency*t)*(1+p.frequency*t);else if(p.damping<1){const b=p.frequency*Math.sqrt(1-p.damping**2);response=1-Math.exp(-a*t)*(Math.cos(b*t)+a/b*Math.sin(b*t));}else{const b=p.frequency*Math.sqrt(p.damping**2-1);response=1-((a+b)*Math.exp((-a+b)*t)-(a-b)*Math.exp((-a-b)*t))/(2*b);}return {primary:M('Step-response output',p.gain*p.amplitude*response),metrics:[M('Final output',p.gain*p.amplitude),M('Relative overshoot',p.damping<1?100*Math.exp(-Math.PI*p.damping/Math.sqrt(1-p.damping**2)):0,'%'),M('Approximate 2% settling',4/(p.frequency*(p.damping>1?p.damping-Math.sqrt(p.damping**2-1):p.damping)),'s'),M('Peak time',p.damping<1?Math.PI/(p.frequency*Math.sqrt(1-p.damping**2)):'No oscillatory peak','s')]};},references:[{label:'Critical damping at unit time',input:{gain:1,amplitude:1,frequency:1,damping:1,time:1},expected:1-2/Math.E},{label:'Critical damping at two seconds',input:{gain:1,amplitude:1,frequency:1,damping:1,time:2},expected:1-3*Math.exp(-2)}]}),
D({id:'pid-effort',title:'PID Control Effort Workbench',desc:'Inspect proportional, integral and derivative contributions with output saturation.',tone:'violet',sweep:'setpoint',fields:[F('kp','Proportional gain Kp',2,0,1e4),F('ki','Integral gain Ki',1,0,1e4),F('kd','Derivative gain Kd',.2,0,1e4),F('setpoint','Setpoint',1,-1e4,1e4),F('measurement','Measured value',.5,-1e4,1e4),F('integral','Accumulated error (unit·s)',.1,-1e6,1e6),F('derivative','Error derivative (unit/s)',.05,-1e6,1e6),F('limit','Symmetric actuator limit',12,.001,1e6)],equation:'u = clamp[Kp·e + Ki·∫e dt + Kd·de/dt, −limit, +limit]',note:'Instantaneous ideal parallel PID calculation, not a closed-loop plant simulation. Integral state and error derivative are supplied; derivative filtering and anti-windup dynamics are not assumed.',calculate:p=>{const proportional=p.kp*(p.setpoint-p.measurement),integral=p.ki*p.integral,derivative=p.kd*p.derivative,raw=proportional+integral+derivative;return {primary:M('Actuator command',Math.max(-p.limit,Math.min(p.limit,raw))),status:Math.abs(raw)>p.limit?'Actuator saturated':'Within actuator range',metrics:[M('Proportional contribution',proportional),M('Integral contribution',integral),M('Derivative contribution',derivative),M('Unclipped command',raw)]};},references:[{label:'Sum of three control terms',input:{kp:2,ki:1,kd:1,setpoint:1,measurement:0,integral:.5,derivative:.2,limit:10},expected:2.7},{label:'Actuator saturation',input:{kp:2,ki:1,kd:1,setpoint:1,measurement:0,integral:.5,derivative:.2,limit:1},expected:1}]}),
D({id:'butterworth-response',title:'Butterworth Filter Response',desc:'Explore cutoff, filter order and frequency-domain attenuation.',tone:'violet',sweep:'frequency',fields:[F('order','Filter order',3,1,12,1),F('cutoff','Cutoff frequency (Hz)',1000,.01,1e7),F('frequency','Signal frequency (Hz)',1500,0,1e7),F('gain','DC gain (dB)',0,-60,60)],equation:'Gain(dB) = Gdc − 10·log10[1 + (f/fc)^(2n)]',note:'Ideal analog all-pole Butterworth magnitude response. Component tolerance, loading and digital frequency warping are not included.',calculate:p=>{const db=p.gain-10*Math.log10(1+(p.frequency/p.cutoff)**(2*p.order));return {primary:M('Magnitude gain',db,'dB'),metrics:[M('Linear amplitude gain',10**(db/20)),M('Cutoff gain',p.gain-10*Math.log10(2),'dB'),M('Asymptotic roll-off',-20*p.order,'dB/decade'),M('Normalized frequency',p.frequency/p.cutoff)]};},references:[{label:'Half-power at cutoff',input:{gain:0,order:1,cutoff:100,frequency:100},expected:-10*Math.log10(2)},{label:'First order at twice cutoff',input:{gain:0,order:1,cutoff:100,frequency:200},expected:-10*Math.log10(5)}]}),
D({id:'chebyshev-response',title:'Chebyshev-I Filter Response',desc:'Trade passband ripple for sharper transition-band rejection.',tone:'violet',sweep:'frequency',fields:[F('order','Filter order',4,1,12,1),F('ripple','Passband ripple (dB)',.5,.001,10),F('cutoff','Passband-edge frequency (Hz)',1000,.01,1e7),F('frequency','Signal frequency (Hz)',1200,0,1e7)],equation:'|H|² = 1/[1 + ε²Tn(f/fc)²]; ε² = 10^(ripple/10)−1',note:'Ideal analog Type-I Chebyshev magnitude. Even-order filters start at the low-ripple extremum, so DC gain is −ripple rather than zero.',calculate:p=>{const x=p.frequency/p.cutoff,polynomial=x<=1?Math.cos(p.order*Math.acos(x)):Math.cosh(p.order*Math.acosh(x)),epsilon=Math.expm1(p.ripple*Math.LN10/10),db=-10*Math.log10(1+epsilon*polynomial**2);return {primary:M('Magnitude gain',db,'dB'),metrics:[M('Linear amplitude gain',10**(db/20)),M('Passband ripple',p.ripple,'dB'),M('Chebyshev polynomial Tn',polynomial),M('Asymptotic roll-off',-20*p.order,'dB/decade')]};},references:[{label:'Ripple depth at passband edge',input:{order:4,ripple:1,cutoff:100,frequency:100},expected:-1},{label:'Second order at DC',input:{order:2,ripple:.5,frequency:0},expected:-.5}]}),
D({id:'moving-average-fir',title:'Moving-Average FIR Analyzer',desc:'Inspect boxcar attenuation, first spectral null and group delay.',tone:'violet',sweep:'frequency',fields:[F('count','Averaging window (samples)',8,1,1000,1),F('sampleRate','Sampling frequency (Hz)',1000,.01,1e7),F('frequency','Signal frequency (Hz)',50,0,5e6)],validate:p=>p.frequency>p.sampleRate/2?'Use a frequency at or below the Nyquist limit.':null,equation:'|H(f)| = |sin(πNf/fs)/[N·sin(πf/fs)]|; delay = (N−1)/(2fs)',note:'Uniform N-tap moving average with unit DC gain. Magnitude is evaluated inside the first Nyquist interval; taps have exact linear phase.',calculate:p=>{const x=Math.PI*p.frequency/p.sampleRate,h=p.frequency===0?1:Math.abs(Math.sin(p.count*x)/(p.count*Math.sin(x)));return {primary:M('Passed amplitude',100*h,'%'),metrics:[M('Group delay',(p.count-1)/(2*p.sampleRate),'s'),M('First null frequency',p.count===1?'No spectral null':p.sampleRate/p.count,'Hz'),M('Nyquist frequency',p.sampleRate/2,'Hz'),M('DC gain',1)]};},references:[{label:'Unit DC gain',input:{count:8,sampleRate:1000,frequency:0},expected:100},{label:'Two-tap response at fs/4',input:{count:2,sampleRate:1000,frequency:250},expected:100/Math.sqrt(2)}]}),
D({id:'sampling-alias',title:'Sampling & Aliasing Explorer',desc:'Fold an input tone into its observable Nyquist-band frequency.',tone:'violet',sweep:'frequency',fields:[F('sampleRate','Sampling frequency (Hz)',1000,.001,1e9),F('frequency','Analog tone frequency (Hz)',750,0,1e10)],equation:'falias = |((fin + fs/2) mod fs) − fs/2|',note:'Ideal sampling of a single sinusoid. Frequency magnitude folds into [0, fs/2]; phase inversion, analog anti-alias filtering and multitone ambiguity are not modeled.',calculate:p=>({primary:M('Observed alias frequency',Math.abs((p.frequency+p.sampleRate/2)%p.sampleRate-p.sampleRate/2),'Hz'),metrics:[M('Nyquist frequency',p.sampleRate/2,'Hz'),M('Sampling period',1/p.sampleRate,'s'),M('Nearest sample harmonic',Math.round(p.frequency/p.sampleRate)),M('Original input frequency',p.frequency,'Hz')]}),references:[{label:'750 Hz sampled at 1 kHz',input:{sampleRate:1000,frequency:750},expected:250},{label:'1.2 kHz sampled at 1 kHz',input:{sampleRate:1000,frequency:1200},expected:200}]}),
D({id:'friis-noise-cascade',title:'Cascaded Amplifier Noise Figure',desc:'See how early-stage gain suppresses downstream receiver noise.',tone:'violet',sweep:'gain1',fields:[F('gain1','Stage 1 power gain (dB)',15,0,80),F('nf1','Stage 1 noise figure (dB)',2,0,60),F('gain2','Stage 2 power gain (dB)',10,0,80),F('nf2','Stage 2 noise figure (dB)',5,0,60),F('gain3','Stage 3 power gain (dB)',5,0,80),F('nf3','Stage 3 noise figure (dB)',8,0,60)],equation:'Ftotal = F1 + (F2−1)/G1 + (F3−1)/(G1·G2)',note:'Friis noise formula with linear power gains and noise factors, matched stages and standard 290 K reference temperature. Stage 3 gain affects total gain, not input-referred noise.',calculate:p=>{const g1=10**(p.gain1/10),g2=10**(p.gain2/10),factor=10**(p.nf1/10)+(10**(p.nf2/10)-1)/g1+(10**(p.nf3/10)-1)/(g1*g2);return {primary:M('Total noise figure',10*Math.log10(factor),'dB'),metrics:[M('Equivalent noise temperature',290*(factor-1),'K'),M('Total power gain',p.gain1+p.gain2+p.gain3,'dB'),M('Linear noise factor',factor),M('Stage 1 noise figure',p.nf1,'dB')]};},references:[{label:'Only first stage adds noise',input:{nf1:3,nf2:0,nf3:0},expected:3},{label:'Unity gains add excess factors',input:{gain1:0,gain2:0,nf1:10*Math.log10(2),nf2:10*Math.log10(2),nf3:10*Math.log10(2)},expected:10*Math.log10(4)}]}),
D({id:'charge-pump-pll',title:'Charge-Pump PLL Loop Parameters',desc:'Calculate natural frequency and damping from a passive PI loop filter.',tone:'violet',sweep:'resistance',fields:[F('current','Charge-pump current (µA)',100,.01,1e5),F('vco','VCO gain (MHz/V)',10,.001,1e4),F('divider','Feedback division N',100,1,1e6,1),F('resistance','Loop-filter resistance (Ω)',1000,.01,1e7),F('capacitance','Loop-filter capacitance (nF)',10,.001,1e7)],equation:'ωn = √[(Ip/2π)·Kvco/(N·C)]; ζ = ωn·R·C/2',note:'Continuous-time Type-II second-order approximation, with Kvco converted to rad/s/V. Extra filter poles, sampling effects, capture range and nonlinear lock behavior are excluded.',calculate:p=>{const c=p.capacitance*1e-9,w=Math.sqrt(p.current*1e-6*p.vco*1e6/(p.divider*c)),z=w*p.resistance*c/2;return {primary:M('Natural loop frequency',w/(2*Math.PI),'Hz'),metrics:[M('Damping ratio',z),M('Natural angular frequency',w,'rad/s'),M('Filter zero frequency',1/(2*Math.PI*p.resistance*c),'Hz'),M('Pump phase-detector gain',p.current*1e-6/(2*Math.PI),'A/rad')]};},references:[{label:'Nominal 100:1 PLL',input:{current:100,vco:10,divider:100,capacitance:10},expected:Math.sqrt(1e9)/(2*Math.PI)},{label:'Four times capacitance halves frequency',input:{current:100,vco:10,divider:100,capacitance:40},expected:Math.sqrt(1e9)/(4*Math.PI)}]}),
D({id:'two-point-calibration',title:'Two-Point Sensor Calibration',desc:'Map a raw sensor reading to calibrated engineering units and inspect extrapolation.',tone:'violet',sweep:'reading',fields:[F('rawLow','Low reference raw reading',0,-1e6,1e6),F('rawHigh','High reference raw reading',1023,-1e6,1e6),F('physicalLow','Low reference engineering value',0,-1e6,1e6),F('physicalHigh','High reference engineering value',100,-1e6,1e6),F('reading','Current raw reading',512,-1e6,1e6)],validate:p=>p.rawHigh<=p.rawLow?'The high raw reference must exceed the low raw reference.':null,equation:'value = lowValue + (raw−lowRaw)·(highValue−lowValue)/(highRaw−lowRaw)',note:'Exact affine two-point calibration. Engineering units are arbitrary and must be consistent at both references; nonlinearity, hysteresis and uncertainty are not inferred.',calculate:p=>{const gain=(p.physicalHigh-p.physicalLow)/(p.rawHigh-p.rawLow);return {primary:M('Calibrated reading',p.physicalLow+(p.reading-p.rawLow)*gain,'EU'),warning:p.reading<p.rawLow||p.reading>p.rawHigh?'Reading is outside the calibration span; this result is an extrapolation.':null,metrics:[M('Calibration slope',gain,'EU/raw'),M('Calibration offset',p.physicalLow-gain*p.rawLow,'EU'),M('Position within raw span',100*(p.reading-p.rawLow)/(p.rawHigh-p.rawLow),'%'),M('Engineering span',p.physicalHigh-p.physicalLow,'EU')]};},references:[{label:'Midscale 10-bit sensor',input:{rawLow:0,rawHigh:1023,physicalLow:0,physicalHigh:100,reading:511.5},expected:50},{label:'Inverted engineering span',input:{rawLow:0,rawHigh:10,physicalLow:100,physicalHigh:0,reading:2},expected:80}]})
];